def parse_amount(text: str) -> int:
    """Parses "12.50", "12.5", "980" or an accounting negative "(3.40)" into cents."""
    s = text.strip().replace(",", "")
    negative = s.startswith("(") and s.endswith(")")
    if negative:
        s = s[1:-1]
    whole, _, frac = s.partition(".")
    cents = int(whole or "0") * 100 + int(frac or "0")
    return cents


def format_cents(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"
from datetime import date


def parse_date(text: str) -> date:
    """Accepts ISO dates (2026-01-31) and day-first dates (31/01/2026)."""
    s = text.strip()
    if "-" in s:
        y, m, d = (int(p) for p in s.split("-"))
        return date(y, m, d)
    first, second, year = (int(p) for p in s.split("/"))
    return date(year, first, second)


def month_key(d: date) -> str:
    return f"{d.year}-{d.month:02d}"
